use crate::core;
use crate::types::*;

// Re-export handlers from core
pub use crate::core::{ToxAVConferenceHandler, ToxAVHandler};

// The flat per-method safe wrappers on `ToxAV` are generated by apigen as
// mechanical delegations over the `core` tier; they are pulled in here as an
// extra `impl` block. The struct definition, `new` and `audio_send_frame`
// (which derives `sample_count` from the PCM buffer) stay hand-written.
#[path = "../core/generated/safe_toxav.rs"]
mod safe_toxav;

pub struct ToxAV<'a, H: ToxAVHandler> {
    pub(crate) inner: core::ToxAV<'a, H>,
    _parent: &'a crate::tox::Tox,
}

impl<'a, H: ToxAVHandler> ToxAV<'a, H> {
    pub fn new(tox: &'a crate::tox::Tox, handler: H) -> Result<Self> {
        // Tox wrapper has .inner which is Arc<Inner>, Inner has .core
        let inner = core::ToxAV::new(&tox.inner.core, handler).map_err(ToxError::AvNew)?;
        Ok(ToxAV {
            inner,
            _parent: tox,
        })
    }

    // The flat per-method wrappers (`call`, `answer`, `video_send_frame`,
    // `iteration_interval`, ...) are generated in `safe_toxav.rs`. The methods
    // below stay hand-written: the `*_iterate` family needs `&mut self` (the
    // dispatch runs `&mut handler` callbacks), and `audio_send_frame` derives
    // `sample_count` from the PCM buffer length.
    pub fn iterate(&mut self) {
        self.inner.iterate();
    }

    pub fn audio_iterate(&mut self) {
        self.inner.audio_iterate();
    }

    pub fn video_iterate(&mut self) {
        self.inner.video_iterate();
    }

    pub fn audio_send_frame(
        &self,
        friend_number: FriendNumber,
        pcm: &[i16],
        channels: u8,
        sampling_rate: u32,
    ) -> Result<()> {
        // Calculate samples per channel from interleaved PCM buffer.
        let sample_count = pcm.len() / (channels as usize);
        self.inner
            .audio_send_frame(friend_number, pcm, sample_count, channels, sampling_rate)
            .map_err(ToxError::AvSendFrame)
    }
}
